import { buildReminderText, unpaidMembers } from '@/domain/dues';
import { requireUser } from '@/services/auth';
import { handle } from '@/services/http';
import { loadFee, loadStatuses } from '@/services/dues';

// Admins get everyone (RLS lets them); members get only their own row.
export async function GET() {
  return handle(async () => {
    const { db, role } = await requireUser();
    const [fee, statuses] = await Promise.all([loadFee(db), loadStatuses(db)]);
    const reminder = role === 'admin' ? buildReminderText(unpaidMembers(statuses), fee) : null;
    return { role, fee, statuses, reminder };
  });
}

