'use client';
import { useCallback, useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import type { FeeSetting, MemberStatus } from '@/domain/dues';
import { call } from '@/ui/api';
import { FeeForm } from '@/ui/FeeForm';
import { StatusList } from '@/ui/StatusList';
import { Reminder } from '@/ui/Reminder';

type Data = { role: 'admin' | 'member'; fee: FeeSetting | null; statuses: MemberStatus[]; reminder: string | null };

export default function Home() {
  const router = useRouter();
  const [data, setData] = useState<Data | null>(null);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    try { setData(await call<Data>('/api/dues')); setError(''); }
    catch (e) {
      const m = (e as Error).message;
      if (m.includes('로그인')) router.replace('/login'); else setError(m);
    }
  }, [router]);
  useEffect(() => { load(); }, [load]);

  async function toggle(memberId: string, paid: boolean) {
    try { await call('/api/payments', 'POST', { memberId, status: paid ? 'paid' : 'unpaid' }); await load(); }
    catch (e) { setError((e as Error).message); }
  }
  async function logout() {
    try { await call('/api/login', 'DELETE'); router.replace('/login'); }
    catch (e) { setError((e as Error).message); }
  }

  if (error) return <p role="alert">{error}</p>;
  if (!data) return <p>불러오는 중…</p>;
  const admin = data.role === 'admin';
  return (
    <main>
      <h1>동아리 회비</h1>
      <p>{data.fee ? `회비 ${data.fee.amount.toLocaleString('ko-KR')}원 · 기한 ${data.fee.due_date}` : '회비가 아직 설정되지 않았습니다.'}</p>
      {admin && <FeeForm fee={data.fee} onSaved={load} />}
      <StatusList rows={data.statuses} editable={admin} onToggle={toggle} />
      {admin && <Reminder text={data.reminder} />}
      <button onClick={logout}>로그아웃</button>
    </main>
  );
}

